-- 090_commercial_health.sql
-- Roadmap F.35: live project commercial health with company-configurable thresholds.
CREATE TABLE IF NOT EXISTS public.company_commercial_health_settings(
 company_key text PRIMARY KEY CHECK(btrim(company_key)<>''),attention_overrun_pct numeric(8,3)NOT NULL DEFAULT 0,at_risk_overrun_pct numeric(8,3)NOT NULL DEFAULT 5,significant_variance_pct numeric(8,3)NOT NULL DEFAULT 10,updated_by uuid NOT NULL REFERENCES auth.users(id)ON DELETE RESTRICT,updated_at timestamptz NOT NULL DEFAULT now(),CHECK(attention_overrun_pct>=0 AND at_risk_overrun_pct>attention_overrun_pct AND significant_variance_pct>at_risk_overrun_pct)
);
ALTER TABLE public.company_commercial_health_settings ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS commercial_health_settings_select ON public.company_commercial_health_settings;CREATE POLICY commercial_health_settings_select ON public.company_commercial_health_settings FOR SELECT TO authenticated USING(true);
REVOKE ALL ON TABLE public.company_commercial_health_settings FROM PUBLIC,anon,authenticated,service_role;GRANT SELECT ON TABLE public.company_commercial_health_settings TO authenticated;

CREATE OR REPLACE FUNCTION public.get_project_commercial_health(p_project_id bigint)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$
DECLARE u uuid:=auth.uid();r text;p public.projects%ROWTYPE;a public.project_tender_awards%ROWTYPE;f public.project_cost_forecast_versions%ROWTYPE;b public.approved_budget_baselines%ROWTYPE;s public.company_commercial_health_settings%ROWTYPE;cur text;approved numeric;pending numeric;committed numeric;forecast numeric;potential numeric;variance numeric;variance_pct numeric;signal text;
BEGIN SELECT lower(role)INTO r FROM public.profiles WHERE id=u;SELECT *INTO p FROM public.projects WHERE id=p_project_id;IF p.id IS NULL THEN RAISE EXCEPTION'PROJECT_NOT_FOUND'USING ERRCODE='P0002';END IF;IF u IS NULL OR r NOT IN('pm','admin')OR public.can_write_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'COMMERCIAL_HEALTH_FORBIDDEN'USING ERRCODE='42501';END IF;
SELECT *INTO a FROM public.project_tender_awards WHERE project_id=p_project_id ORDER BY awarded_at DESC LIMIT 1;cur:=COALESCE(a.currency_code,p.currency_code,'USD');SELECT *INTO b FROM public.approved_budget_baselines WHERE project_id=p_project_id AND currency_code=cur;SELECT *INTO f FROM public.project_cost_forecast_versions WHERE project_id=p_project_id ORDER BY version_number DESC LIMIT 1;SELECT *INTO s FROM public.company_commercial_health_settings WHERE company_key=COALESCE(p.company_id,'__GLOBAL__');IF s.company_key IS NULL THEN s.attention_overrun_pct:=0;s.at_risk_overrun_pct:=5;s.significant_variance_pct:=10;END IF;
SELECT COALESCE(sum(approved_amount)FILTER(WHERE status='APPROVED'AND currency_code=cur),0),COALESCE(sum(proposed_amount)FILTER(WHERE status IN('SUBMITTED','UNDER_REVIEW','REVISION_REQUIRED')AND currency_code=cur),0)INTO approved,pending FROM public.project_variations WHERE project_id=p_project_id;committed:=CASE WHEN a.id IS NULL THEN NULL ELSE a.contract_value+approved END;forecast:=COALESCE(f.forecast_final_cost,committed);potential:=CASE WHEN f.id IS NULL THEN CASE WHEN committed IS NULL THEN NULL ELSE committed+pending END ELSE f.potential_final_cost END;variance:=CASE WHEN b.id IS NULL OR forecast IS NULL THEN NULL ELSE forecast-b.total_amount END;variance_pct:=CASE WHEN b.total_amount>0 AND variance IS NOT NULL THEN variance/b.total_amount*100 ELSE NULL END;
signal:=CASE WHEN a.id IS NULL OR b.id IS NULL OR forecast IS NULL THEN'INCOMPLETE'WHEN variance_pct<=s.attention_overrun_pct THEN'WITHIN_BUDGET'WHEN variance_pct<s.at_risk_overrun_pct THEN'ATTENTION'WHEN variance_pct<s.significant_variance_pct THEN'AT_RISK'ELSE'SIGNIFICANT_VARIANCE'END;
RETURN jsonb_build_object('projectId',p_project_id,'companyId',p.company_id,'currencyCode',cur,'signal',signal,'approvedBudget',b.total_amount,'awardedContractValue',a.contract_value,'approvedVariations',approved,'pendingVariations',pending,'currentCommittedCost',committed,'forecastFinalCost',forecast,'potentialExposure',pending,'potentialFinalCost',potential,'certifiedValue',NULL,'paidToDate',NULL,'retentionHeld',NULL,'paymentMetricsAvailable',false,'forecastVsBudget',variance,'forecastVsBudgetPct',variance_pct,'thresholds',jsonb_build_object('attentionOverrunPct',s.attention_overrun_pct,'atRiskOverrunPct',s.at_risk_overrun_pct,'significantVariancePct',s.significant_variance_pct));END;$$;

CREATE OR REPLACE FUNCTION public.save_company_commercial_health_settings(p_project_id bigint,p_attention_overrun_pct numeric,p_at_risk_overrun_pct numeric,p_significant_variance_pct numeric,p_client_request_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE u uuid:=auth.uid();r text;p public.projects%ROWTYPE;k text;req public.write_command_requests%ROWTYPE;result jsonb;BEGIN SELECT lower(role)INTO r FROM public.profiles WHERE id=u;SELECT *INTO p FROM public.projects WHERE id=p_project_id;k:=COALESCE(p.company_id,'__GLOBAL__');IF p.id IS NULL OR u IS NULL OR r<>'admin'OR public.can_admin_company(p.company_id)IS NOT TRUE THEN RAISE EXCEPTION'COMMERCIAL_HEALTH_SETTINGS_FORBIDDEN'USING ERRCODE='42501';END IF;IF p_client_request_id IS NULL OR p_attention_overrun_pct<0 OR p_at_risk_overrun_pct<=p_attention_overrun_pct OR p_significant_variance_pct<=p_at_risk_overrun_pct THEN RAISE EXCEPTION'INVALID_COMMERCIAL_HEALTH_THRESHOLDS'USING ERRCODE='22023';END IF;
INSERT INTO public.write_command_requests(actor_id,operation,client_request_id,project_id)VALUES(u,'commercial_health.settings',p_client_request_id,p_project_id)ON CONFLICT(actor_id,operation,client_request_id)DO NOTHING;SELECT *INTO req FROM public.write_command_requests WHERE actor_id=u AND operation='commercial_health.settings'AND client_request_id=p_client_request_id;IF req.response IS NOT NULL THEN RETURN req.response||jsonb_build_object('idempotentReplay',true);END IF;INSERT INTO public.company_commercial_health_settings VALUES(k,p_attention_overrun_pct,p_at_risk_overrun_pct,p_significant_variance_pct,u,now())ON CONFLICT(company_key)DO UPDATE SET attention_overrun_pct=EXCLUDED.attention_overrun_pct,at_risk_overrun_pct=EXCLUDED.at_risk_overrun_pct,significant_variance_pct=EXCLUDED.significant_variance_pct,updated_by=u,updated_at=now();result:=jsonb_build_object('companyKey',k,'attentionOverrunPct',p_attention_overrun_pct,'atRiskOverrunPct',p_at_risk_overrun_pct,'significantVariancePct',p_significant_variance_pct);UPDATE public.write_command_requests SET response=result,completed_at=now()WHERE id=req.id;RETURN result||jsonb_build_object('idempotentReplay',false);END;$$;
REVOKE ALL ON FUNCTION public.get_project_commercial_health(bigint),public.save_company_commercial_health_settings(bigint,numeric,numeric,numeric,uuid)FROM PUBLIC,anon,authenticated,service_role;GRANT EXECUTE ON FUNCTION public.get_project_commercial_health(bigint),public.save_company_commercial_health_settings(bigint,numeric,numeric,numeric,uuid)TO authenticated;
